//! Нарушение §3.2: anyhow для доменных ошибок.

use anyhow::Result;

pub fn settle(amount: i64) -> Result<()> {
    if amount <= 0 {
        anyhow::bail!("amount must be positive");
    }
    Ok(())
}

//! Соблюдение §3.2: доменные ошибки — собственный тип.

#[derive(Debug, PartialEq, Eq)]
pub enum PaymentError {
    NonPositiveAmount,
}

pub fn settle(amount: i64) -> Result<(), PaymentError> {
    if amount <= 0 {
        return Err(PaymentError::NonPositiveAmount);
    }
    Ok(())
}

//! Формальный обход: anyhow используется, но под переименованным крейтом `ah`.
//! В исходнике нет ни `anyhow::`, ни `anyhow!`, ни `use anyhow` — правило
//! по токену `anyhow` может не сработать, требование §3.2 нарушено.

use ah::{bail, Result};

pub fn settle(amount: i64) -> Result<()> {
    if amount <= 0 {
        bail!("amount must be positive");
    }
    Ok(())
}

//! Нарушение §3.2: тип ошибки стёрт через Box<dyn Error>.

pub fn load(path: &str) -> Result<String, Box<dyn std::error::Error>> {
    let body = std::fs::read_to_string(path)?;
    Ok(body)
}

//! Соблюдение §3.2: тип ошибки сохранён.

#[derive(Debug)]
pub enum PaymentError {
    Unreadable(String),
}

pub fn load(path: &str) -> Result<String, PaymentError> {
    std::fs::read_to_string(path).map_err(|e| PaymentError::Unreadable(e.to_string()))
}

//! Формальный обход: абсолютный путь к модулю — тип ошибки всё равно стёрт.
//! Паттерн по `std::error::Error` мог не поймать ведущее `::`.

pub fn load(path: &str) -> Result<String, Box<dyn ::std::error::Error>> {
    let body = std::fs::read_to_string(path)?;
    Ok(body)
}

//! Нарушение §4.1: authorize не принимает ключ идемпотентности.

pub struct Payment {
    authorized: bool,
}

impl Payment {
    pub fn authorize(&mut self) {
        self.authorized = true;
    }
}

//! Соблюдение §4.1: authorize идемпотентен по ключу.

use std::collections::HashMap;

#[derive(Default)]
pub struct PaymentProcessor {
    inbox: HashMap<String, bool>,
}

impl PaymentProcessor {
    pub fn authorize(&mut self, idempotency_key: &str) -> bool {
        if let Some(result) = self.inbox.get(idempotency_key) {
            return *result;
        }
        self.inbox.insert(idempotency_key.to_owned(), true);
        true
    }
}

//! Формальный обход: ключа нет, но слово idempotency есть в комментарии.
//! Повторный вызов повторит операцию — требование §4.1 нарушено,
//! проверка «слово есть в src» может пройти.

// TODO(TASK-9): добавить idempotency key перед продуктива.

pub struct Payment {
    authorized: bool,
}

impl Payment {
    pub fn authorize(&mut self) {
        self.authorized = true;
    }
}

