pub fn discounted(total_minor: i64) -> i64 {
    let rate = 0.985;
    total_minor / 100 * (rate * 100.0) as i64
}

//! Соблюдение §2.1: только целые минорные единицы.

pub fn discounted(total_minor: i64) -> i64 {
    total_minor - total_minor * 15 / 1000
}

